        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And straightway coming up out of the water, he saw the heavens opened, and the Spirit like a dove descending upon him&#x27; — Cyril marks the Trinitarian-theophany at Jordan: the Father&#x27;s-voice (1:11), the Son-incarnate-in-the-water, the Spirit-descending-as-dove. The schizomenous (rent-open, Mk 1:10) is stronger than Matthew&#x27;s aneōchthēsan (opened, Mt 3:16) — Mark&#x27;s heaven-torn anticipates the temple-veil-torn at Mk 15:38 (the same schizō). The peristera (dove) recalls Gen 8:8-12 (Noahic-flood-dove-new-creation) and Cant 2:14 (Bridegroom&#x27;s-beloved). Tewahedo Tǝmqät (Epiphany) liturgy on Ṭǝrr 11 reads the Markan baptism explicitly with Cyrillian-Trinitarian emphasis.</p></aside>',
