        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Come ye after me, and I will make you to become fishers of men&#x27; — Cyril marks the deute opisō mou (come after me) as the discipleship-call language reused at Mk 8:34 (take-up-cross). The halieis-anthrōpōn (fishers of men) metaphor draws on the disciples&#x27; existing-occupation but transposes it from fish-into-net to souls-into-kingdom. Tewahedo episcopal-vocation rhetoric frequently cites Mk 1:17 as the call-of-pastoral-leaders text.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
