        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;What have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art, the Holy One of God&#x27; — Cyril marks the Capernaum-demoniac&#x27;s confession as ironic-theological-priority: the unclean spirits identify the incarnate Word (ho hagios tou theou — the Holy One of God, echoing Ps 16:10 LXX hosios) before the disciples do. The demonic-Christology runs ahead of human-Christology throughout Mark (again at 3:11, 5:7). Tewahedo exorcism-rite cites Mk 1:24 + Acts 16:17 as the demons-recognize-Christ formula.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
