        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And in the morning, rising up a great while before day, he went out, and departed into a solitary place, and there prayed&#x27; — Cyril marks the prōi-ennycha-lian (very-early-while-still-night) solitary-prayer as the Christic-pattern of contemplation. The erēmon topon (solitary place) is the typological wilderness — Christ goes-to-the-wilderness-to-pray repeatedly through Mark&#x27;s Gospel. Tewahedo monastic vigil-prayer tradition (the morning-office in the Mahǝlet cycle) cites Mk 1:35 + Lk 6:12 + Heb 5:7 as the dawn-prayer Christic-warrant.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
