        38,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Let us go into the next towns, that I may preach there also: for therefore came I forth&#x27; — Cyril marks eis touto exēlthon (for this I came forth) as the Christic mission-self-declaration. The exēlthon may signify both &#x27;came from prayer&#x27; (Markan immediate context) AND &#x27;came forth from the Father&#x27; (Johannine-deeper sense Jn 16:28). Cyril reads both layers simultaneously. The missionary-urgency principle is grounded: Christ moves to the next towns rather than settling where success has come. Tewahedo itinerant-evangelism tradition appeals here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
