        41,
        "",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Jesus, moved with compassion, put forth his hand, and touched him, and saith unto him, I will; be thou clean&#x27; — Cyril marks splanchnistheis (moved-in-the-bowels-with-compassion) as the deepest Markan compassion-verb. The leper&#x27;s prior request (ean-thelēs, if-thou-wilt) is met by Christ&#x27;s echoing thelō (I-will, Mk 1:41). The kerygmatic-touch reverses Levitical-transmission: purity flows from Christ to leper, not the reverse. Tewahedo healing-prayer tradition (the bahǝtawi monastic healing-ministry) traces here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
