        14,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And as he passed by, he saw Levi the son of Alphaeus sitting at the receipt of custom, and said unto him, Follow me. And he arose and followed him&#x27; — Cyril marks the Markan-distinctive Levi (named as son-of-Alphaeus here; Matthew&#x27;s Mt 9:9 names him simply &#x27;Matthew&#x27; — same person, two Christian names per ancient practice). The immediate-following (anastas ēkolouthēsen) mirrors Mk 1:18 fishermen-leaving-nets. Tewahedo conversion-narrative tradition cites the Markan immediacy + Matthean restraint as the call-paradigm.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
