        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;No man putteth new wine into old bottles: else the new wine doth burst the bottles, and the wine is spilled, and the bottles will be marred: but new wine must be put into new bottles&#x27; — Cyril reads the oinos-neos / askoi-kainoi pairing as covenantal-renewal: the new-covenant-grace cannot be poured-into-the-unrenewed-Pharisaic-structures. Both wine-and-skin must be transformed-together (cf. Mt 9:17 γ.4.6.C). Tewahedo liturgical-innovation theology (incorporating Aksumite-Ethiopian tradition into received Coptic-Alexandrian forms — the foundational pattern of the Tewahedo Church&#x27;s emergence from Coptic origin via Frumentius) appeals to Mk 2:22 as legitimate creative-reception.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
