        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Therefore the Son of man is Lord also of the sabbath&#x27; — Cyril marks the Markan-conclusion (kyrios estin ho hyios tou anthrōpou kai tou sabbatou) as the Sabbath-Christology-summit. The Son-of-Man (incarnate-Word) is the Sabbath-Lord precisely because he is the Lord-of-Creation who instituted the Sabbath at Gen 2:2-3. Tewahedo Sabbath-as-Christic-rest theology (paired with Heb 4:9-10 sabbatismos remaining-rest) anchors here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
