        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And when he had looked round about on them with anger, being grieved for the hardness of their hearts&#x27; — Cyril marks the met&#x27; orgēs (with-anger) + syllypoumenos (being-grieved) pairing as the only Gospel-passage that explicitly attributes orgē (anger) to the incarnate Word. The orgē is righteous-anger at human-obstinacy (pōrōsis — hardening); the syllype is divine-grief at the same. The dual-affect demonstrates that righteous-anger and compassion-grief co-exist non-contradictorily in the divine-moral-life. Tewahedo Christology preserves both affections as authentic-human-emotion in the incarnate Word without divine-passibility-defect.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
