        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Unclean spirits, when they saw him, fell down before him, and cried, saying, Thou art the Son of God&#x27; — Cyril marks the Markan-recurring demonic-Christology (cf. Mk 1:24 γ.4.7 anchor). The Mark 3:11 occurrence is collective (plural unclean-spirits) and prosaic (recurring-pattern, not single-dramatic-confession). Christ silences them (Mk 3:12 immediately) per the messianic-secret motif — demons-confess-before-disciples-do is the wrong-epistemic-order. Tewahedo exorcism-rite cites Mk 3:11 + Mk 1:24 + Mk 5:7 + Acts 16:17 as the four-fold demons-recognize-Christ corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
