        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He goeth up into a mountain, and calleth unto him whom he would: and they came unto him&#x27; — Cyril marks anabainei-eis-to-oros (he-goes-up-into-the-mountain) as the mountain-of-commissioning. The mountain is a deliberate-locational-typology: Sinai (Moses + Torah-giving), Tabor (Transfiguration), Olivet (Ascension), and now this-unnamed-Galilean-mountain (Twelve-commissioning). The hous-ēthelen-autos (whom-he-himself-willed) emphasizes Christic-election. Tewahedo episcopal-consecration tradition cites Mk 3:13-14 as the Christic-selection prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
