        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he ordained twelve, that they should be with him, and that he might send them forth to preach&#x27; — Cyril marks epoiēsen dōdeka (made-twelve) as the deliberate-symbolism: twelve-tribes-of-Israel restored in twelve-apostolic-foundation. The hina ōsin met&#x27; autou (that-they-might-be-with-him) precedes the hina apostellē (that-he-might-send) — being-with-Christ founds every-apostolic-sending. Tewahedo episcopal-formation tradition cites Mk 3:14 as the dual-mandate (formation-then-mission).</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
