        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Simon he surnamed Peter; And James the son of Zebedee, and John the brother of James; and he surnamed them Boanerges, which is, The sons of thunder&#x27; — Cyril marks the Mark-distinctive Boanerges (sons-of-thunder, hyioi-brontēs) name-giving. The Aramaic-Greek transliterated name signals James&#x27;s + John&#x27;s fiery-zealous character (cf. Lk 9:54 &#x27;shall we call down fire?&#x27;). Naming-by-Christ is divine-prerogative (Gen 17:5 Abram-Abraham; Mt 16:18 Simon-Peter). Tewahedo apostle-veneration tradition cites Mk 3:17 for James-John&#x27;s distinctive Boanerges-vocation.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
