    (
        3,
        21,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;When his friends heard of it, they went out to lay hold on him: for they said, He is beside himself&#x27; — Cyril treats Mk 3:21 (Markan-distinctive) with great pastoral care: hoi par&#x27; autou (those-with-him, his family per the immediate-context) thought him exestē (out-of-his-mind, frenzied). This is a strong word; Cyril notes that Mary is NOT among the accusers — she alone has received the angelic-disclosure of who Jesus actually is (Lk 1:35). The familial-misunderstanding is a real-fact of the incarnate Word&#x27;s hiddenness-in-ordinary-Galilean-life. Tewahedo Marian-distinction theology emphasizes Mary-as-only-faithful-in-the-family in the early-ministry-period.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
    ),
