        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;He hath Beelzebub, and by the prince of the devils casteth he out devils&#x27; — Cyril marks the Markan Jerusalem-scribes&#x27; charge (parallels Mt 12:24 γ.4.6.C anchor) as the gravest possible misreading: Spirit-driven exorcism mistaken for demon-driven exorcism. The &#x27;they came down from Jerusalem&#x27; (Mk 3:22) signals official-investigation by Sanhedrin-aligned scribes. Tewahedo doctrinal-discernment catechesis cites Mk 3:22-30 + Mt 12:22-32 + Lk 11:14-23 as the triple Beelzebub-controversy corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
