        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;No man can enter into a strong man&#x27;s house, and spoil his goods, except he will first bind the strong man; and then he will spoil his house&#x27; — Cyril marks the strong-man-binding parable as the positive-counterpart to the divided-kingdom argument. Christ (stronger than Satan) has-bound-the-strong-man (Satan, binding happened at Christ&#x27;s-Temptation in Mk 1:13 victory and ongoing-exorcisms) and is-spoiling-his-house (rescuing-the-possessed). Tewahedo exorcism-theology grounds the apostolic-authority over demons in Mk 3:27 + Lk 11:21-22 + Heb 2:14 triple-prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
