        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For whosoever shall do the will of God, the same is my brother, and my sister, and my mother&#x27; — Cyril reads the Markan-version (slightly shorter than Mt 12:50) carefully — not as displacement of Mary but as expansion of kinship via obedience. Mary supremely-does-the-Father&#x27;s-will (Lk 1:38 fiat-mihi); she is thus doubly-mother (by-flesh + by-obedience). Tewahedo Marian-theology reads Mk 3:35 + Mt 12:50 + Lk 11:27-28 as the obedience-based-kinship anchor that ENHANCES rather than diminishes Marian-veneration.</p></aside>',
