        "",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he said unto them, He that hath ears to hear, let him hear&#x27; — Cyril marks ho echōn ōta akouein akouetō as the hermeneutical imperative concluding the Sower-parable. The same formula appears throughout the prophets (Isa 6:9-10, Jer 5:21, Ezek 12:2). The hearing-faculty is not biological-hearing but receptive-comprehension; not all who hear-with-ears hear-with-hearts. Tewahedo mystagogical-catechesis (the gradual-revelation-pattern of the qǝddus-mystēria) cites Mk 4:9 as the receptive-disposition anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
