        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Unto you it is given to know the mystery of the kingdom of God: but unto them that are without, all these things are done in parables&#x27; — Cyril marks the Markan-singular &#x27;mystery&#x27; (mystērion, vs Matthew&#x27;s plural &#x27;mysteries&#x27; Mt 13:11) as the deliberate-concentration: the central-mystery is Christ-himself. The tois-exō (those-outside) is not predestinarian-exclusion but epistemic-positioning: those who refuse-the-clear-word now receive-the-veiled-word. Tewahedo mystagogical-catechesis pedagogy (the qǝddus-mystēria gradual-revelation) is grounded here.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
