        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Have no root in themselves, and so endure but for a time: afterward, when affliction or persecution ariseth for the word&#x27;s sake, immediately they are offended&#x27; — Cyril marks the thlipsis-ē-diōgmos (affliction or persecution) pair as the test-of-rootedness. The euthys-skandalizontai (immediately-they-are-scandalized) is the time-test failure-mode for emotionally-received-but-not-internally-grounded faith. Tewahedo martyr-preparation catechesis cites Mk 4:17 + Heb 12:1-4 as the rootedness-for-endurance anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
