        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The cares of this world, and the deceitfulness of riches, and the lusts of other things entering in, choke the word, and it becometh unfruitful&#x27; — Cyril marks the Markan-fuller list (cares + deceit-of-riches + lusts-of-other-things; Matthew has &#x27;cares-of-this-life + deceit-of-riches&#x27;; Luke has &#x27;cares + riches + pleasures-of-life&#x27;) as the comprehensive-distraction taxonomy. Each component is a strangling-thorn. Tewahedo monastic-renunciation theology (the three monastic-vows: poverty + chastity + obedience) maps onto Cyril&#x27;s three-thorns precisely.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
