        31,
        "",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;It is like a grain of mustard seed, which, when it is sown in the earth, is less than all the seeds that be in the earth&#x27; — Cyril marks the Markan-comparative (less-than-all-seeds, NOT in Mt 13:31&#x27;s compact-form) as deliberate-hyperbole emphasizing the imperceptible-smallness-of-the-kingdom&#x27;s-beginning. The mikroteron pantōn-tōn-spermatōn (smaller-than-all-the-seeds) is phenomenological-observation (the apparent-smallest seed of Palestinian agriculture), not botanical-precision. The kingdom&#x27;s-beginning at a Galilean rabbi&#x27;s twelve fishermen IS the imperceptibly-small seed. Tewahedo missionary-theology — specifically the Frumentius-founding-narrative (one shipwrecked Christian captive becomes the seed of an entire national-Church) — reads Mk 4:30-32 as exact-fulfillment.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
