        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he was in the hinder part of the ship, asleep on a pillow: and they awake him, and say unto him, Master, carest thou not that we perish?&#x27; — Cyril marks the Markan-distinctive &#x27;asleep on a pillow&#x27; (epi to proskephalaion, on the cushion) as the humanity-of-the-incarnate-Word: he genuinely-sleeps in his exhaustion. The disciples&#x27; ou-melei-soi (carest-thou-not) rebuke reveals their flicker-of-doubt-in-his-divinity even after his-many-miracles. Tewahedo Christology preserves the fully-human-tiredness in the Person-of-the-Word without divine-passibility-defect.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
