        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm&#x27; — Cyril marks the Markan-direct-address (siōpa pephimōso, Peace! Be muzzled!) as the divine-prerogative speech to the elements. The verb pephimōso (be muzzled) is the SAME verb used of demon-silencing (Mk 1:25); creation-and-demons obey the same Christic-fiat. The galēnē-megalē (great calm) is the immediate-divine-effect. Tewahedo natural-disaster-prayer tradition cites Mk 4:39 as the storm-rebuke Christic-warrant.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
