        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;The unclean spirits went out, and entered into the swine: and the herd ran violently down a steep place into the sea, (they were about two thousand;) and were choked in the sea&#x27; — Cyril marks the Markan-detail &#x27;about two thousand&#x27; (hōs dischilioi) swine as the realistic-scale of the herd. The unclean-spirits-into-unclean-animals symbolic-disposition is theological: demons belong to the swine-realm, not the human-realm. The mass-drowning visualizes-the-judgment that demons have-been-spared. Tewahedo exorcism rite preserves the symbolic-transfer pattern in expulsion-formulae.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
