        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;They come to Jesus, and see him that was possessed with the devil, and had the legion, sitting, and clothed, and in his right mind&#x27; — Cyril marks the post-exorcism-image: kathēmenon (sitting — opposite of his prior wandering-among-tombs), himatismenon (clothed — opposite of his prior naked-self-harming), sōphronounta (in-his-right-mind — opposite of his prior madness). The triple-restoration is comprehensive-rehumanization. Tewahedo restored-person ministry cites Mk 5:15 as the holistic-deliverance pattern.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
