        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For she said, If I may touch but his clothes, I shall be whole&#x27; — Cyril marks the hemorrhaging-woman&#x27;s silent confessional-faith (elegen — she was saying, internally). The ean-hapsōmai-kan-tōn-himatiōn-autou (if-only-I-may-touch-even-his-clothes) is the humble-grasp-at-the-hem (Markan-version preserves the same anchor as Mt 9:21 γ.4.6.C). The kraspedon-touching faith-pattern Tewahedo Mary-as-Tabot iconographic-pilgrim-touch tradition explicitly inherits.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
