        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Jesus, immediately knowing in himself that virtue had gone out of him, turned him about in the press, and said, Who touched my clothes?&#x27; — Cyril marks the Markan-distinctive epignous-en-heautō (knowing-in-himself) + tēn-ex-autou-dynamin-exelthousan (the-virtue-having-gone-out-of-him) as the Christic-knowledge-of-the-touch. The dynamis-going-out is the divine-energy operating-through-Christ&#x27;s-bodily-presence; the Christic-knowledge is comprehensive (no faith-touch escapes notice). Tewahedo iconographic-veneration theology grounds the icon-touch dynamics in Mk 5:30 + the Theotokos-Tabot dynamics.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
