        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague&#x27; — Cyril marks hē pistis sou sesōken se (thy-faith-hath-saved-thee) as the Markan-double-meaning: the Greek sōzō means both &#x27;heal-physically&#x27; and &#x27;save-spiritually&#x27;. The woman receives both. The thygater (daughter) vocative is the only-Gospel-instance of Christ-addressing-an-unrelated-woman as &#x27;daughter&#x27; — an extraordinary intimacy-of-adoption. Tewahedo Mary-and-women-saints hagiography cites Mk 5:34 as the daughter-by-faith adoption-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
