        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he took the damsel by the hand, and said unto her, Talitha cumi; which is, being interpreted, Damsel, I say unto thee, arise&#x27; — Cyril marks the Markan-preserved-Aramaic talitha-cum (little-girl, arise) as the linguistically-intimate detail. Mark preserves the actual-words-spoken in their original-Aramaic — eyewitness-tradition pattern. The Christic-power-over-death-itself is exercised through tender-gentle-address (not dramatic-incantation). Tewahedo resurrection-theology + Fasika anticipation cite Mk 5:41 + Lk 7:14 + Jn 11:43 as the triple Christic-raising-from-death corpus.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
