        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he called unto him the twelve, and began to send them forth by two and two&#x27; — Cyril marks duo duo (two-by-two) as the Markan-distinctive (Matthew gives the full list without the pairing-detail). The twofold-sending fulfills Deut 19:15 (two-witnesses confirm-every-word) and the mutual-pastoral-support principle. Tewahedo missionary-tradition explicitly preserves the two-by-two pattern in the Frumentius + Edesius founding-pair (two brothers-by-faith brought the Gospel to Aksum together), the Nine-Saints arrival (six-and-three in groups), and contemporary pastoral-deputation patterns.</p></aside>',
