        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And when he had taken the five loaves and the two fishes, he looked up to heaven, and blessed, and brake the loaves, and gave them to his disciples to set before them&#x27; — Cyril marks the four-action sequence (anablepsas-eulogēsen-kateklasen-edidou: looked-up + blessed + broke + gave) as the Eucharistic prototype (echoed at Mk 14:22 institution). The Galilean-multiplication is the proleptic Anaphora. Tewahedo Qǝddāse fraction-rite cites Mk 6:41 + Mt 14:19 + Lk 9:16 + Jn 6:11 + Mk 14:22 as the five-fold lineage of the institution-action-sequence.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
