        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And she answered and said unto him, Yes, Lord: yet the dogs under the table eat of the children&#x27;s crumbs&#x27; — Cyril celebrates the Syrophoenician-woman&#x27;s faith-quickness. The diminutives (kynaria-paidia — little-dogs / little-children) soften the harshness; her witty-faith reply matches Christ&#x27;s-witty-test. The psichiōn (crumbs) image — even the crumbs of Israel&#x27;s kingdom-bread overflow to the Gentile-table — is the early-inclusion charter. Tewahedo missionary-theology cites Mk 7:24-30 + Mt 15:21-28 + Acts 10 as the triple Gentile-inclusion witness; the Tewahedo Church&#x27;s Aksumite origin among Cushite-Gentile peoples reads here as fulfillment.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
