        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Whosoever will come after me, let him deny himself, and take up his cross, and follow me&#x27; — Cyril&#x27;s discipleship-summit text. The aparnēsasthō heauton (deny-himself) is not mere ascetic-self-denial but the renunciation of self-as-center; the aratō ton stauron autou (take-up-his-cross) is the willingness-to-share-the-Master&#x27;s-fate; the akoloutheitō moi (let-him-follow) is the lifelong-relational-commitment. The three-imperatives compress the entire-discipleship-rule. Tewahedo monastic-vocation theology (the Mäshafä-Mǝnǝkwǝsnna rule-prologue) cites Mk 8:34 + Mt 16:24 + Lk 9:23 as the triple cross-bearing-charter.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
