        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;What therefore God hath joined together, let not man put asunder&#x27; — Cyril&#x27;s marital-indissolubility locus (paired with Mt 19:6 γ.4.6.D anchor). The theou synezeuxen (God-hath-joined) names divine-agency in marriage; the mē chōrizetō (let-not-separate) is imperative-prohibition. The Markan-context (10:11-12) extends the prohibition to women-divorcing-husbands — a Greco-Roman possibility outside the Jewish-context, signaling Mark&#x27;s Gentile-readership. Tewahedo marital-discipline preserves the Cyrillian strictness conservatively.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
