        45,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many&#x27; — Cyril&#x27;s atonement-summit text. The lytron anti pollōn (ransom-for-many) is the explicit-atonement-formula; lytron is the redemption-payment language (Ex 30:12, Isa 53). The peri / anti pollōn (for-many, Septuagintal-Isa-53 echo) names the universal-scope. The diakonēsai (to-minister) inverts the ancient world&#x27;s lord-served-by-slaves dynamic. Tewahedo Anaphora-theology cites Mk 10:45 + Mt 20:28 + 1 Tim 2:6 as the triple ransom-formula anchor; the Qǝddāse explicitly cites &#x27;gave-his-life-a-ransom-for-many&#x27; at the institution.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
