        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Hosanna; Blessed is he that cometh in the name of the Lord&#x27; — Cyril marks hōsanna (the transliterated Aramaic &#x27;save-now&#x27; from Ps 118:25 LXX) as the eschatological-acclamation. The eulogēmenos ho erchomenos en onomati Kyriou (blessed-is-he-who-comes-in-the-name-of-the-Lord, Ps 118:26 LXX) is the messianic-acclamation. The Hosanna-Sunday Tewahedo liturgy (the Sunday before Fasika) preserves the Markan procession-form alongside Matthean and Johannine fulfillment-texts.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
