        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Is it not written, My house shall be called of all nations the house of prayer? but ye have made it a den of thieves&#x27; — Cyril marks the Markan-distinctive (only Mark preserves the &#x27;for-all-the-nations&#x27; phrase from Isa 56:7 in the temple-cleansing). The Markan-version makes the universal-mission explicit: the temple was supposed to be the meeting-place for-all-nations; the Pharisaic-commercialization perverted it into a national-ethnic-exclusive-marketplace. Tewahedo missionary-theology — the Coptic-Tewahedo opening-to-Cushite-Gentile-nations from the Frumentius-mission forward — reads Mk 11:17 as fulfillment of the temple-for-all-nations promise in the new-covenant-Church.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
