        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;Thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first commandment&#x27; — Cyril marks the Markan-fourfold-form (heart + soul + mind + strength — kardia + psychē + dianoia + ischys; Matthew gives threefold at Mt 22:37) as the fullest Synoptic-form of the great-commandment. The ischys (strength) addition emphasizes the bodily-strength-dimension of total-consecration. Tewahedo catechetical-totality teaches the four-fold love-of-God as the comprehensive-anthropological-formation.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
