        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And there came a certain poor widow, and she threw in two mites, which make a farthing&#x27; — Cyril marks the widow&#x27;s-mite (lepta duo — two-smallest-coins) as the kenotic-stewardship summit. The Markan-detail (only-Mark + Luke preserve this; Matthew omits) shows Christ-noticing-what-others-miss. The hē hysterēsis autēs (her-poverty, Mk 12:44) gave more-than-all-the-rich because she gave from her bios (life-substance) not perissou (abundance). Tewahedo monastic-and-lay stewardship-formation cites Mk 12:41-44 + Lk 21:1-4 as the kenotic-giving foundational text.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
