        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And ye shall be hated of all men for my name&#x27;s sake: but he that shall endure unto the end, the same shall be saved&#x27; — Cyril marks the hypomeinas eis telos as the eschatological-perseverance summary (cf. Mt 10:22, Mt 24:13 γ.4.6.D). The misoumenoi (hated-ones) precedes the sōthēsetai (shall-be-saved) — endurance-through-hostility, not absence-of-hostility, is the eschatological-promise. Tewahedo Sämā&#x27;ǝtāt martyrology cites Mk 13:13 as the perseverance-charter.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
