        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;She hath done what she could: she is come aforehand to anoint my body to the burying&#x27; — Cyril marks the Markan-version of the anointing-at-Bethany (paired with Mt 26:13 γ.4.6.D, Lk 7:36-50). The proelaben myrisai mou to sōma eis ton entaphiasmon (she-came-beforehand to-anoint-my-body for-the-burying) names her prophetic-action: she alone among the disciples recognized that the Master-was-going-to-die and-needed-burial-anointing-now. The Markan eis mnēmosynon autēs (memorial-of-her, Mk 14:9) is Christ&#x27;s-own-canonization of one of the few-named-female-acts in the Gospel. Tewahedo Marian + women-saints hagiography reads Mk 14:3-9 as the proto-prophetic-female-disciple anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
