        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And he said, Abba, Father, all things are possible unto thee; take away this cup from me: nevertheless not what I will, but what thou wilt&#x27; — Cyril marks the Markan-distinctive Abba ho patēr (the Aramaic Abba preserved alongside the Greek translation) as the deepest-filial-intimacy. The transferral to Christian-prayer is at Rom 8:15 + Gal 4:6 (the Spirit-of-adoption cries &#x27;Abba, Father&#x27;). The Gethsemane-cup is the Passion-cup (cf. Mt 26:39 γ.4.6 seed, Lk 22:42 γ.4.3.D). The two-wills (parelthe ap&#x27; emou + thelō / ou-thelō pattern) names the Cyrillian Miaphysite Christology: the one-incarnate-Person genuinely-prays-with-human-volition while-perfectly-aligned-with-divine-will. Tewahedo prayer-formation cites Mk 14:36 + Rom 8:15 as the Abba-adoption baptismal-anchor.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
