        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (430).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on Mark</em> <small>(c. 430 AD)</small><p>&#x27;And when the centurion, which stood over against him, saw that he so cried out, and gave up the ghost, he said, Truly this man was the Son of God&#x27; — Cyril marks the centurion-confession (alēthōs houtos ho anthrōpos hyios theou ēn) as the Markan-thematic-climax: the very Gospel-opening claim (1:1 — &#x27;the gospel of Jesus Christ, the Son of God&#x27;) is now confirmed BY A GENTILE at the Cross. The structural-inclusio frames the entire Gospel between divine-Sonship-declaration and Gentile-confession-fulfillment. Tewahedo missionary-theology reads Mk 15:39 (paired with Mt 27:54 γ.4.6.D) as the Gentile-inclusion-at-the-Cross definitive prooftext.</p></aside>',
        "Cyril of Alexandria, Commentary on Mark (fragments), preserved in J.A. Cramer, Catenae Graecorum Patrum in Novum Testamentum, Vol. I: In Evangelia S. Matthaei et S. Marci (Oxford: University Press, 1840). PD. Greek text also in PG 72 (Migne, 1859).",
